1	<%/* The design surface: one page of the design, framed, under the design bar.
2	
3	     Two kinds of change reach it, and they're treated differently:
4	       - the person's own (a page, a state, a size, Reset data, Show, a
5	         window popping out): the whole surface is a region that answers
6	         with itself and reloads on design-changed, so every window moves
7	         at once;
8	       - the agent's (the design's files, its design system, its shell): only
9	         the head reloads (#design-bar, on files-changed), and the frame keeps
10	         the page as the person left it, until they load the changes
11	         (_design-bar.eta, R-v2q).
12	
13	     The frame is the page itself: an iframe on the design's own origin, or
14	     the app's in App mode. At a size, the page is laid out at that width and
15	     height and scaled down to fit the panel.
16	
17	     `view` is 'inline' (beside the chat) or 'window' (the pop-out). While a
18	     window is open, the inline surface shrinks to its bar. */%>
19	<% const s = it.surface; const q = it.$query ?? {};
20	   const base = `/f/${it.folder.id}/d/${it.id}`;
21	   const view = it.view ?? q.view ?? s.view ?? 'inline';
22	   const appMode = Boolean(s.app) && (q.mode ?? s.mode) === 'app';
23	   const pixels = value => { const n = Math.round(Number(value)); return n >= 200 && n <= 4000 ? n : null; };
24	   const custom = pixels(s.custom?.width) && pixels(s.custom?.height)
25	     ? { id: 'custom', title: 'Custom', width: pixels(s.custom.width), height: pixels(s.custom.height) } : null;
26	   const sizes = custom ? [...s.sizes, custom] : s.sizes;
27	   const size = sizes.find(x => x.id === (q.size ?? s.size)) ?? sizes[0];
28	   const client = s.clients.find(x => x.id === (q.client ?? s.client)) ?? s.clients[0];
29	   const here = { view, mode: appMode ? 'app' : 'design', size: size.id, client: client.id };
30	   const url = `${base}/preview?${new URLSearchParams(here)}`;
